#!/usr/bin/env node
/**
 * C17.2 I — machine-verifiable Linux/macOS artifact comparison.
 *
 * The C17.1 record said eight artifacts had been compared across hosts, but the comparison was
 * performed interactively and no comparison artifact survived.  This module turns that claim
 * into evidence.  It consumes the C17 source archive produced by the Linux `supply-chain` job
 * and the outputs regenerated by the macOS finalizer, compares the exact code-owned nine-file
 * set byte-for-byte, and emits one deterministic finalization ZIP containing:
 *
 *   * the original Linux source archive;
 *   * the nine macOS-generated artifact bytes and its C17 manifest;
 *   * a canonical comparison document;
 *   * the hosted finalizer receipt; and
 *   * a complete, non-self-referential SHA-256 manifest.
 *
 * Verification recomputes every claim from those bytes. Online verification constructs every
 * GitHub API endpoint from code-owned repository/workflow/job/artifact constants and the receipt's
 * strictly numeric run id. The receipt never chooses an endpoint. An injected verifier/fetch
 * exists only so mutation controls can prove the same production path without using the network.
 */
import {
  appendFileSync, chmodSync, cpSync, lstatSync, mkdirSync, mkdtempSync, readFileSync,
  readdirSync, realpathSync, rmSync, utimesSync, writeFileSync,
} from 'node:fs';
import { createHash } from 'node:crypto';
import { tmpdir } from 'node:os';
import { dirname, isAbsolute, join, relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import {
  apiGet, API_ORIGIN, FINALIZED_ARTIFACT_PREFIX, finalizerArtifactPrefixForAttempt,
  selectAttemptArtifact,
} from './lib/hosted-run.mjs';

const sha256 = (bytes) => createHash('sha256').update(bytes).digest('hex');
const SHA40 = /^[0-9a-f]{40}$/;
const POSITIVE_INTEGER = /^[1-9][0-9]{0,17}$/;
const FIXED_MTIME = new Date('1980-01-01T00:00:00.000Z');

export const REPOSITORY = 'a-Halawany/elven';
export const SOURCE_OS = 'Linux';
export const FINALIZER_OS = 'macOS';
export const SOURCE_ARCH = 'X64';
export const FINALIZER_ARCH = 'ARM64';
export const SOURCE_WORKFLOW_REF = `${REPOSITORY}/.github/workflows/ci.yml@refs/heads/main`;
export const FINALIZER_WORKFLOW_REF = `${REPOSITORY}/.github/workflows/c17-finalize.yml@refs/heads/main`;
export const FINALIZER_WORKFLOW_PATH = '.github/workflows/c17-finalize.yml';
export const FINALIZER_WORKFLOW_NAME = 'C17 finalize';
export const FINALIZER_JOB = 'finalize';
/**
 * The uploaded artifact name carries the finalizer's OWN run attempt and the SHA-256 of the
 * INNER finalized ZIP. GitHub authenticates this name through its API, which binds the exact ZIP
 * a reviewer verifies to the completed run and attempt. The API's own `digest` describes GitHub's
 * wrapper archive, not this inner ZIP, so existence plus a fixed name would not be a byte-level
 * provenance claim. The naming contract itself is CENTRALIZED in lib/hosted-run.mjs — this module
 * deliberately owns no second implementation of it.
 */
export const FINALIZER_EVENT = 'workflow_run';
export const FINALIZER_BRANCH = 'main';
export const FINALIZER_REF = `refs/heads/${FINALIZER_BRANCH}`;
export const FINALIZER_RUNNER_LABEL = 'macos-14';
export const REQUIRED_FINALIZER_STEPS = Object.freeze([
  'Check out the EXACT source the run was made from',
  'Install dependencies (materializes the declared linux-x64-glibc target)',
  'Download the archive the SOURCE run produced',
  'Verify the source C17 archive online and hosted',
  'Generate FINAL C16 + C17 artifacts on macOS ARM64',
  'Create + verify the finalized cross-host evidence',
  'Upload the FINALIZED cross-host evidence',
]);
/**
 * The MEASURED size of the development target closure.
 *
 * It is a measurement, not a policy: the finalizer asserts that both hosts see the
 * same closure and that the closure is the one this source declares. So it moves
 * only when a merged dependency change moves it, and every move is reconciled
 * package by package before this line is touched.
 *
 * 312 → 320 at `045ee030` (PR #28, Phase 1). That merge added ONE direct
 * dependency — `fast-xml-parser@5.11.1`, used by the RSS/XML connector in
 * `apps/api/src/observation/connectors/xml-worker.js` — and version 5 of that
 * package is modular, so it brings seven transitive packages with it:
 *
 *   fast-xml-parser  → @nodable/entities, fast-xml-builder, is-unsafe,
 *                      path-expression-matcher, strnum, xml-naming
 *   fast-xml-builder → xml-naming, path-expression-matcher   (already counted)
 *   strnum           → anynum
 *
 * That closes at exactly eight new packages, all published by the same author as
 * `fast-xml-parser` itself (Amit Gupta / NaturalIntelligence), each pinned in the
 * lockfile by the integrity hash the registry serves. 312 + 8 = 320, and the count
 * has not moved since — Phase 2 (`6b4b22d6`) and PR #33 (`ea7b3089`) added no
 * dependencies and both reported 320.
 */
export const DEVELOPMENT_COMPONENTS = 320;
export const COMPARISON_SCHEMA = '1.0.0';

/**
 * The exact target-artifact set.  C17.1 had eight; bundled-components.json makes the current
 * contract nine.  Manifests and receipts bind the run but are not counted as target artifacts.
 */
